import { Dispatcher } from "@fanfanlo";
// import { projectStore } from "../storage";
import { projectStore } from "@droid/project-interface";
import { initProjectSystem } from "./ProjectInit";
export class ProjectModel extends Dispatcher{

    constructor(){
        super();
    }

    async init(){
        console.log('[ProjectModel.init] 开始初始化ProjectModel')
        initProjectSystem()
        console.log('[ProjectModel.init] initProjectSystem 调用完成')
        projectStore.init()
        console.log('[ProjectModel.init] ProjectModel初始化完成')
    }
    



}

export const projectModel = new ProjectModel();
