import { useProxyWatch, useTranslation } from '@fanfanlo';
import { Box, TextField, FormControl, FormLabel, Dialog, DialogTitle, DialogContent, DialogActions, Button, IconButton, Tooltip, Select, MenuItem } from '@mui/material';
import HelpIcon from '@mui/icons-material/Help';
import { useState } from 'react';
import { PermissionsEditorAdapter } from './PermissionsEditorAdapter';

export interface ScriptEditorProps {
  /**
   * 脚本数据对象
   */
  data: {
    javaData: {
      script: string
      scriptMode: 'simple' | 'advanced' | 'full'
    }
  }
  /**
   * 简单模式的模板代码
   */
  simpleTemplate: string
  /**
   * 高级模式的模板代码
   */
  advancedTemplate: string
  /**
   * 完整模式的模板代码
   */
  fullTemplate: string
  /**
   * 简单模式说明文字（非通用，需注入）
   */
  simpleModeDescription: string
  /**
   * 高级模式说明文字（非通用，需注入）
   */
  advancedModeDescription: string
  /**
   * 完整模式说明文字（非通用，需注入）
   */
  fullModeDescription: string
  /**
   * UI 类型：'trigger' 或 'action'，用于日志和 id 前缀
   */
  type?: 'trigger' | 'action'
  /**
   * 代码编辑区的行数
   */
  rows?: number
}

export function ScriptEditor({
  data,
  simpleTemplate,
  advancedTemplate,
  fullTemplate,
  simpleModeDescription,
  advancedModeDescription,
  fullModeDescription,
  type = 'trigger',
  rows = 12
}: ScriptEditorProps) {
  const { t } = useTranslation('droid-project/iproject/script-editor/content');
  const [script] = useProxyWatch(data, 'javaData.script', data.javaData.script);
  const [scriptMode] = useProxyWatch(data, 'javaData.scriptMode', data.javaData.scriptMode);
  const [templateDialogOpen, setTemplateDialogOpen] = useState(false);

  console.log(`[ScriptEditor.${type}] 当前script:`, script);
  console.log(`[ScriptEditor.${type}] 当前scriptMode:`, scriptMode);

  const currentTemplate = scriptMode === 'simple' ? simpleTemplate :
                          scriptMode === 'advanced' ? advancedTemplate :
                          fullTemplate;

  // 根据模式生成 placeholder
  const getPlaceholder = () => {
    if (scriptMode === 'simple') {
      return type === 'trigger'
        ? `setTimeout(() => {\n  that.dispatchConditionsOn({ data: that.data });\n}, 3000);`
        : `setTimeout(() => {\n  that.dispatchSuccess();\n}, 1000);`;
    } else if (scriptMode === 'advanced') {
      return type === 'trigger'
        ? `let domain = {};\nlet logger = that.logger.subLogger('ScriptTrigger');\n\n// 清理资源\nfunction clean() {\n  a11yModel.removeDomain(that);\n  that.removeDomain(domain);\n}\n\n// 重写 onRun\nlet superOnRun = that.onRun;\nthat.onRun = function() {\n  superOnRun();\n  // TODO: 添加你的逻辑\n};`
        : `let logger = that.logger;\nlet domain = {};\n\n// 清理资源\nfunction clean() {\n  a11yModel.removeDomain(domain);\n}\n\n// 重写 doAction\nlet superDoAction = that.doAction;\nthat.doAction = function() {\n  superDoAction();\n  // TODO: 添加你的执行逻辑\n  that.dispatchSuccess();\n};`;
    } else {
      return currentTemplate;
    }
  };

  return (
    <>
      <Box sx={{ width: '100%' }}>
        <Box sx={{ width: '100%', gap: 1, display: 'flex', flexDirection: 'column' }}>
          {/* 脚本模式选择 */}
          <Box>
            <FormControl sx={{ width: '100%' }} size="small">
              <FormLabel sx={{ mb: 0.5 }}>{t('scriptEditor.scriptMode')}</FormLabel>
              <Select
                value={scriptMode}
                onChange={(e) => {
                  console.log(`[ScriptEditor.${type}] 修改scriptMode:`, e.target.value);
                  data.javaData.scriptMode = e.target.value as 'simple' | 'advanced' | 'full';
                }}
              >
                <MenuItem value="simple">{t('scriptEditor.scriptMode_simple')}</MenuItem>
                <MenuItem value="advanced">{t('scriptEditor.scriptMode_advanced')}</MenuItem>
                <MenuItem value="full">{t('scriptEditor.scriptMode_full')}</MenuItem>
              </Select>
            </FormControl>
          </Box>

          {/* 脚本代码编辑区 */}
          <Box>
            <Box sx={{ mb: 0.5, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <span>{t('scriptEditor.scriptCode')}</span>
              <Box>
                <Tooltip title={t('scriptEditor.showTemplate')}>
                  <IconButton
                    size="small"
                    onClick={() => setTemplateDialogOpen(true)}
                    aria-label="show-template"
                  >
                    <HelpIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
              </Box>
            </Box>
            <TextField
              id={`${type}-script-code-textarea`}
              data-id={`${type}-script-code-textarea`}
              multiline
              rows={rows}
              value={script}
              onChange={(e) => {
                console.log(`[ScriptEditor.${type}] 修改script值, 长度:`, e.target.value.length);
                data.javaData.script = e.target.value;
              }}
              placeholder={getPlaceholder()}
              sx={{
                width: '100%',
                fontFamily: 'monospace',
                fontSize: '12px'
              }}
            />
          </Box>

          {/* 模式说明 */}
          <Box sx={{ p: 1, bgcolor: '#f5f5f5', borderRadius: 1 }}>
            <Box sx={{ fontSize: '12px', color: '#666' }}>
              <Box><b>{t('scriptEditor.modeDescription')}</b></Box>
              {scriptMode === 'simple' && (
                <Box sx={{ mt: 0.5 }}>
                  {simpleModeDescription}
                </Box>
              )}
              {scriptMode === 'advanced' && (
                <Box sx={{ mt: 0.5 }}>
                  {advancedModeDescription}
                </Box>
              )}
              {scriptMode === 'full' && (
                <Box sx={{ mt: 0.5 }}>
                  {fullModeDescription}
                </Box>
              )}
            </Box>
          </Box>

          {/* Permissions 编辑器 */}
          <Box>
            <PermissionsEditorAdapter data={data} />
          </Box>
        </Box>
      </Box>

      {/* 模板展示对话框 */}
      <Dialog
        open={templateDialogOpen}
        onClose={() => setTemplateDialogOpen(false)}
        maxWidth={false}
        PaperProps={{
          sx: {
            width: 'calc(100vw - 20px)',
            height: '75vh',
            maxHeight: '75vh',
            margin: 0
          }
        }}
      >
        <DialogTitle>
          {t('scriptEditor.templateDialog_title', { mode: scriptMode === 'simple' ? '简单' : scriptMode === 'advanced' ? '高级' : '完整' })}
        </DialogTitle>
        <DialogContent sx={{ display: 'flex', flexDirection: 'column', height: '100%', px: '5px' }}>
          <Box sx={{ mt: 2, flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
            <Box sx={{ mb: 2 }}>
              <span sx={{ fontWeight: 'bold' }}>{t('scriptEditor.templateCode')}</span>
            </Box>
            <TextField
              multiline
              value={currentTemplate}
              InputProps={{
                readOnly: true,
                style: {
                  height: '100%',
                  alignItems: 'flex-start',
                  overflow: 'auto'
                }
              }}
              inputProps={{
                style: {
                  height: '100%',
                  overflow: 'auto'
                }
              }}
              sx={{
                width: '100%',
                flex: 1,
                fontFamily: 'monospace',
                fontSize: '11px',
                backgroundColor: '#f5f5f5',
                '& .MuiInputBase-root': {
                  height: '100%',
                  alignItems: 'flex-start',
                  overflow: 'auto'
                },
                '& .MuiInputBase-input': {
                  overflow: 'auto !important',
                  height: '100% !important'
                }
              }}
            />
          </Box>
          <Box sx={{ mt: 2, fontSize: '12px', color: '#666' }}>
            {t('scriptEditor.templateDescription', { mode: scriptMode === 'simple' ? '简单' : scriptMode === 'advanced' ? '高级' : '完整' })}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setTemplateDialogOpen(false)}>
            {t('scriptEditor.templateDialog_close') || 'Close'}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
}
