import { ulid } from "ulid";
import { createActionUtils, IActionData, IActionJavaData, IActionShellData } from "@droid/project-interface";
import { appNamespace } from "../app-namespace";
import { IActionOpenAppUI } from "./IActionOpenApp.UI";
import { ManifestPermission } from "@droid/android";
import { RhinoInjectNames } from "@app/static";
import { getI18nT, Log } from '@fanfanlo';
import { Namespace } from "i18next";
const type = `${appNamespace}openApp`


export interface IActionOpenAppJavaData extends IActionJavaData {
    packageName: string
}

export interface IActionOpenAppData extends IActionData<IActionShellData, IActionOpenAppJavaData> { 
    javaData: IActionOpenAppJavaData
}

function createDefaultData(): IActionOpenAppData {
    console.log('[IActionOpenApp.createDefaultData] 开始创建默认数据')

    const id = ulid()
    console.log('[IActionOpenApp.createDefaultData] 生成id:', id)

    const permissions = [
        {
            name: '辅助功能权限',
            value: ManifestPermission.BIND_ACCESSIBILITY_SERVICE,
            reason: '需要辅助功能来检测应用是否已打开'
        }
    ]
    console.log('[IActionOpenApp.createDefaultData] 权限数量:', permissions.length)

    const injects: ([typeof RhinoInjectNames.a11yModel, string])[] = [
        [RhinoInjectNames.a11yModel, 'a11yModel']
    ]
    console.log('[IActionOpenApp.createDefaultData] 注入配置数量:', injects.length)

    const defaultData = {
        id,
        type,
        name: 'actionOpenApp',
        permissions,
        injects,
        javaData: {
            packageName: ''
        }
    }
    console.log('[IActionOpenApp.createDefaultData] defaultData:', defaultData)
    return defaultData
}

function init(){
}

// 添加异步加载国际化文本的函数
async function loadI18nTexts(data: IActionOpenAppData): Promise<void> {
    const log = new Log(false, 'loadI18nTexts_fn')
    log.log('开始加载国际化文本')
    log.log('data:', data)

    if (!data.permissions) {
        log.log('data.permissions 为 undefined')
        log.log('跳过加载')
        return
    }
    if (data.permissions.length === 0) {
        log.log('data.permissions 长度为 0')
        log.log('跳过加载')
        return
    }

    // 加载 Manifest 的国际化文本 (权限名称)
    log.log('加载 Manifest 国际化命名空间')
    const manifestT = await getI18nT('droid-android/android/components/content' as Namespace)
    log.log('Manifest 国际化加载完成')

    // 加载 IActionOpenApp 的国际化文本 (权限原因)
    log.log('加载 IActionOpenApp 国际化命名空间')
    const actionT = await getI18nT('droid-project/iproject/actions/app/action-open-app/content')
    log.log('IActionOpenApp 国际化加载完成')

    // 更新权限数据
    const permissionsLength = data.permissions.length
    log.log('权限数量:', permissionsLength)
    for (let i = 0; i < permissionsLength; i++) {
        const permission = data.permissions[i]
        log.log('处理权限索引:', i)
        log.log('permission.value:', permission.value)

        // 从 permission.value 提取 key
        // 例如: "android.permission.BIND_ACCESSIBILITY_SERVICE" -> "BIND_ACCESSIBILITY_SERVICE"
        const valueParts = permission.value.split('.')
        log.log('value 分割后的数组:', valueParts)
        const permissionKey = valueParts.pop() || ''
        log.log('提取的权限 key:', permissionKey)

        // 更新权限名称 (从 Manifest.i18n.json)
        const manifestKey = `Manifest.Permission.${permissionKey}`
        log.log('查找 Manifest key:', manifestKey)
        const nameValue = manifestT(manifestKey as any)
        log.log('获取到的名称:', nameValue)
        permission.name = nameValue
        log.log('已更新 permission.name')

        // 更新权限原因 (从 IActionOpenApp.i18n.json)
        const reasonKey = `IActionOpenApp.permission.a11y.reason`
        log.log('查找 reason key:', reasonKey)
        const reasonValue = actionT(reasonKey)
        log.log('获取到的原因:', reasonValue)
        permission.reason = reasonValue
        log.log('已更新 permission.reason')

        log.log('权限更新完成, 索引:', i)
    }

    log.log('所有权限国际化文本加载完成')
}

export const actionOpenAppUtils = createActionUtils(type, init, createDefaultData, IActionOpenAppUI)

// 添加 loadI18nTexts 方法
actionOpenAppUtils.loadI18nTexts = loadI18nTexts


