/**
 * 脚本动作模板集合
 * 这些是用于展示给用户的示例代码，导出为字符串常量
 * 不作为可执行的代码文件
 */

export const scriptActionSimpleTemplate = `import { regAction } from "#/droid/java_js/fanfanlo/javajs/v1/project/store.java"
import { eventTypeComplete, eventTypeExit } from "#/droid/java_js/fanfanlo/javajs/v1/project/base/projectEventTypes.java"

let type = "fanfanlo/javajs/v1/project/components/actions/script/simple"

onLibReady(() => {
  regAction(type, attach)
}, "fanfanlo/javajs/v1/project/components/actions/script/simple")

function attach(that) {
  let superDoAction = that.doAction;
  let logger = that.logger;
  let domain = {};

  function onScriptCallExit() {
    logger.log("onScriptCallExit", that.baseMsg)
    onExit();
  }

  addScriptExitListener(onScriptCallExit);
  that.dispatcher.listenData(eventTypeExit, onExit);
  that.dispatcher.listenData(eventTypeComplete, onExit);

  function onExit(e) {
    logger.log("ScriptActionOnExit")
    clean();
  }

  function clean() {
    a11yModel.removeDomain(domain)
    removeScriptExitListener(onScriptCallExit);
  }

  that.doAction = doAction.bind(that);

  function doAction() {
    superDoAction();
    executeAction();
  }

  function executeAction() {
    logger.log("executeAction start", that.data)

    try {
      // 简单的脚本动作示例
      // 打开指定的应用包
      let packageName = that.data.packageName;
      logger.log("opening app", packageName)

      com.fanfanlo.lib.intent.Funcs.openApp(packageName);
      logger.log("app opened successfully")

      that.dispatchSuccess();
    } catch (e) {
      logger.log("error executing action", e)
      that.dispatchFailed("动作执行失败: " + e);
    }
  }
}

export { type }`

export const scriptActionAdvancedTemplate = `import { regAction } from "#/droid/java_js/fanfanlo/javajs/v1/project/store.java"
import { eventTypeComplete, eventTypeExit } from "#/droid/java_js/fanfanlo/javajs/v1/project/base/projectEventTypes.java"

let type = "fanfanlo/javajs/v1/project/components/actions/script/advanced"

onLibReady(() => {
  regAction(type, attach)
}, "fanfanlo/javajs/v1/project/components/actions/script/advanced")

function attach(that) {
  let superDoAction = that.doAction;
  let logger = that.logger;
  let domain = {};
  let isExecuting = false;
  let maxRetries = 3;
  let retryCount = 0;

  function onScriptCallExit() {
    logger.log("onScriptCallExit", that.baseMsg)
    onExit();
  }

  addScriptExitListener(onScriptCallExit);
  that.dispatcher.listenData(eventTypeExit, onExit);
  that.dispatcher.listenData(eventTypeComplete, onExit);

  function onExit(e) {
    logger.log("ScriptActionOnExit")
    clean();
  }

  function clean() {
    a11yModel.removeDomain(domain)
    removeScriptExitListener(onScriptCallExit);
  }

  that.doAction = doAction.bind(that);

  function doAction() {
    logger.log("doAction called")
    superDoAction();
    executeAction();
  }

  function executeAction() {
    logger.log("executeAction start", that.data)
    logger.log("isExecuting:", isExecuting)

    if (isExecuting) {
      logger.log("already executing, return")
      return;
    }

    isExecuting = true;
    retryCount = 0;

    tryExecute();
  }

  function tryExecute() {
    logger.log("tryExecute, retryCount:", retryCount)

    try {
      let packageName = that.data.packageName;
      logger.log("opening app", packageName)

      // 打开应用
      com.fanfanlo.lib.intent.Funcs.openApp(packageName);

      // 监听包名变化以验证应用是否真的打开了
      a11yModel.listenDomainData(
        com.fanfanlo.droidlib.auto.service.accessibility.A11yModel.Companion.eventLastPackageChanged,
        domain,
        onPackageChanged
      );

      // 设置超时，如果1秒内没有验证成功就重试
      setTimeout(() => {
        if (isExecuting) {
          retryCount++;
          logger.log("app not verified, retryCount:", retryCount)
          if (retryCount < maxRetries) {
            tryExecute();
          } else {
            logger.log("max retries reached, marking as failed")
            isExecuting = false;
            that.dispatchFailed("应用打开失败：无法验证应用是否成功打开");
          }
        }
      }, 1000);
    } catch (e) {
      logger.log("error executing action", e)
      isExecuting = false;
      that.dispatchFailed("动作执行出错: " + e);
    }
  }

  function onPackageChanged(event) {
    logger.log("package changed event", event)

    let packageName = that.data.packageName;
    let currentPackage = a11yModel.lastFullScreenPackage;

    logger.log("target package:", packageName, "current package:", currentPackage)

    if (currentPackage === packageName) {
      logger.log("app verified as opened")
      isExecuting = false;
      that.dispatchSuccess();
    }
  }
}`

export const scriptActionFullTemplate = scriptActionAdvancedTemplate
