import { ulid } from "ulid";
import { ITriggerData, ITriggerJavaData, ITriggerShellData, createTriggerUtils } from "@droid/project-interface";
import { scriptNamespace } from "../script-namespace";
import { UI } from "./UI";

const type = `${scriptNamespace}script`

export interface ITriggerScriptJavaData extends ITriggerJavaData {
  script: string
  scriptMode: 'simple' | 'advanced' | 'full'
}

export interface ITriggerScriptData extends ITriggerData<ITriggerShellData, ITriggerScriptJavaData> {
  javaData: ITriggerScriptJavaData
}

function createDefaultData(): ITriggerScriptData {
  console.log('[ITriggerScript.createDefaultData] 开始创建默认数据')

  const id = ulid()
  console.log('[ITriggerScript.createDefaultData] 生成id:', id)

  const defaultData: ITriggerScriptData = {
    id,
    type,
    name: 'triggerScript',
    javaData: {
      script: '',
      scriptMode: 'simple'
    }
  }
  console.log('[ITriggerScript.createDefaultData] defaultData:', defaultData)
  return defaultData
}

function init() {
}

export const triggerScriptUtils = createTriggerUtils(type, init, createDefaultData, UI)
