import { toProxy, useProxyWatchUpdates, useTranslation, proxyWatch } from '@fanfanlo';
import { Box, Chip, Stack, Typography } from '@mui/material';
import { AndroidPermissionsButton } from '@droid/ui';
import { useState, useRef, useEffect } from 'react';
import { IPermissionData } from '@droid/project-interface';
import { AndroidPermission, ManifestPermission } from '@droid/android';

// 日志前缀
const LOG_PREFIX = '[PermissionsEditorAdapter]';

/**
 * 比较两个权限数组是否相等（只比较 value 字段）
 */
function isPermissionsEqual(a: IPermissionData[] | undefined, b: IPermissionData[]): boolean {
  const arrayA = a || [];
  const arrayB = b;

  if (arrayA.length !== arrayB.length) {
    return false;
  }

  // 比较每个权限的 value
  for (let i = 0; i < arrayA.length; i++) {
    if (arrayA[i].value !== arrayB[i].value) {
      return false;
    }
  }

  return true;
}

interface PermissionsEditorAdapterProps {
  /**
   * 权限数据对象（直接修改此对象的 permissions 属性）
   */
  data: {
    permissions?: IPermissionData[]
  };
}

/**
 * Permissions 编辑器适配器
 * 将 IPermissionData[] 格式适配到 AndroidPermissionsButton 组件
 * AndroidPermissionsButton 使用的是 AndroidPermission[] 格式（字符串键名数组）
 */
export function PermissionsEditorAdapter({ data }: PermissionsEditorAdapterProps) {
  console.log(`${LOG_PREFIX} 组件初始化`);
  console.log(`${LOG_PREFIX} 输入 data.permissions:`, data.permissions);

  const { t } = useTranslation('droid-project/iproject/script-editor/content');

  // 将 IPermissionData[] 转换为 AndroidPermission[]
  const [permissionsProps] = useState(() => {
    console.log(`${LOG_PREFIX} 创建 permissionsProps 对象`);

    // 从 IPermissionData[] 提取 value 字段作为 AndroidPermission
    const androidPermissions: AndroidPermission[] = (data.permissions || []).map(p => {
      // value 格式如 "android.permission.BIND_ACCESSIBILITY_SERVICE"
      // 需要转换为 AndroidPermission 键名，如 "BIND_ACCESSIBILITY_SERVICE"
      const parts = p.value.split('.');
      const key = parts[parts.length - 1] as AndroidPermission;
      console.log(`${LOG_PREFIX} 转换权限: ${p.value} -> ${key}`);
      return key;
    });

    const props = toProxy({ permissions: androidPermissions });
    console.log(`${LOG_PREFIX} permissionsProps 创建完成, 权限数量: ${androidPermissions.length}`);
    return props;
  });

  // 初始化标记，防止初始化时触发更新
  const isInitializedRef = useRef(false);

  useEffect(() => {
    if (!isInitializedRef.current) {
      isInitializedRef.current = true;
      console.log(`${LOG_PREFIX} 初始化完成`);
      return;
    }
  }, []);

  // 监听 permissionsProps.permissions 的变化，并同步到 data.permissions
  useEffect(() => {
    console.log(`${LOG_PREFIX} 设置 proxyWatch`);

    const {unwatch} = proxyWatch(permissionsProps, 'permissions', (androidPermissions: AndroidPermission[]) => {
      if (!isInitializedRef.current) {
        console.log(`${LOG_PREFIX} 初始化阶段，跳过同步`);
        return;
      }

      console.log(`${LOG_PREFIX} androidPermissions 变化, 准备转换回 IPermissionData[]`);
      console.log(`${LOG_PREFIX} 新权限数量: ${androidPermissions.length}`);

      const newPermissions: IPermissionData[] = androidPermissions.map(key => {
        console.log(`${LOG_PREFIX} 处理权限键: ${key}`);

        // 从 ManifestPermission 获取完整的 value
        const value = ManifestPermission[key as keyof typeof ManifestPermission];
        console.log(`${LOG_PREFIX} 权限值: ${value}`);

        const permissionData: IPermissionData = {
          name: '',  // 将在 UI 层通过国际化填充
          value: value || `android.permission.${key}`,
          reason: ''  // 将在 UI 层通过国际化填充
        };

        return permissionData;
      });

      console.log(`${LOG_PREFIX} 转换完成, 权限数量: ${newPermissions.length}`);

      // 只在权限真正有变化时才更新，避免无意义的赋值导致循环
      if (!isPermissionsEqual(data.permissions, newPermissions)) {
        console.log(`${LOG_PREFIX} 权限有变化，更新 data.permissions`);
        data.permissions = newPermissions;
      } else {
        console.log(`${LOG_PREFIX} 权限无变化，跳过更新`);
      }
    });

    return () => {
      console.log(`${LOG_PREFIX} 清理 proxyWatch`);
      unwatch();
    };
  }, [data]);

  // 监听 permissions 数组的变化以更新 UI
  const [androidPermissions] = useProxyWatchUpdates(permissionsProps, 'permissions', permissionsProps.permissions);

  return (
    <Box>
      <Stack direction="row" spacing={2} alignItems="center">
        <Typography variant="body2" sx={{ fontWeight: 500 }}>
          {t('PermissionsEditorAdapter.label')}:
        </Typography>
        <Chip
          label={`${androidPermissions.length} ${t('PermissionsEditorAdapter.permissionsCount')}`}
          size="small"
          color={androidPermissions.length > 0 ? 'primary' : 'default'}
        />
        <AndroidPermissionsButton permissionsProps={permissionsProps} />
      </Stack>
    </Box>
  );
}
